import java.util.*; class Card{private String rank,suit;Card(String r,String s){rank=r;suit=s;}public String toString(){return rank+" of "+suit;}public boolean equals(Object o){return o instanceof Card c&&rank.equals(c.rank)&&suit.equals(c.suit);}public int hashCode(){return Objects.hash(rank,suit);}}public class CardDriver{public static void main(String[]z){Card[] a={new Card("Ace","Spades"),new Card("King","Hearts"),new Card("Ace","Spades")};Set<Card>s=new HashSet<>();for(Card c:a)if(!s.add(c)){System.out.println("Duplicate found: "+c);break;}}}
